-- 7.3M GPS pings from ships in US waters in 2024 -- where, when, how fast, and what they were carrying.
-- Auto-generated by scripts/gen_evidence_pages.py: 7,296,017 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DATE") as year, count(*) as records
from THE_LIBRARY.TRANSPORT.SHIP_POSITIONS
where "DATE" is not null
group by 1
order by 1
